/** Renders integer cents as dollars (see SPEC.md). */
export function formatCents(cents: number): string {
	const dollars = Math.floor(cents / 100);
	const rest = cents % 100;
	return '$' + dollars + '.' + rest;
}
```

SPEC for formatReceipt:
One line per item, `<label>: <formatCents(cents)>`, then a last line `Total: <formatCents(sum)>`.
Lines are joined with `\n` (no trailing newline). An empty list gives just `Total: $0.00` when formatCents(0) is `$0.00`.
Example: formatReceipt([{ label: 'Tea', cents: 350 }, { label: 'Refund', cents: -100 }]) returns `Tea: $3.50\nRefund: -$1.00\nTotal: $2.50` once formatCents matches the spec. In THIS pass, implement formatReceipt by calling the existing formatCents. Do not rewrite formatCents even if that example cannot pass yet.

Implement exactly:

```ts
/** One receipt line per item plus a total (see SPEC.md). */
export function formatReceipt(lines: Array<{ label: string; cents: number }>): string {
	const rows = lines.map((line) => line.label + ': ' + formatCents(line.cents));
	const sum = lines.reduce((total, line) => total + line.cents, 0);
	rows.push('Total: ' + formatCents(sum));
	return rows.join('\n');
}
```

Append that after formatCents. Change nothing else. When done, report the full file contents.

